const n="// 传统沙箱脚本 - 使用 registerFunction 注册函数\r\n// 上下文变量：$api, $route, $data, $el, $query, $queryAll, $rebindRules, $refreshData, $dataSet, $call 都已注入\r\n\r\n// 页面初始化\r\nconsole.log('⚙️ 系统设置页面已加载 (传统沙箱执行)');\r\nconsole.log('📦 页面数据:', $data);\r\n\r\n// 注册页面函数\r\nregisterFunction('saveSettings', function() {\r\n    alert('💾 保存设置');\r\n    console.log('保存设置');\r\n});\r\n\r\nregisterFunction('resetSettings', function() {\r\n    alert('🔄 重置设置');\r\n    console.log('重置设置');\r\n});\r\n\r\nregisterFunction('exportConfig', function() {\r\n    alert('📤 导出配置');\r\n    console.log('导出配置');\r\n});\r\n";export{n as default};
